@ConfigGroup(GETransactionExporterConfig.GROUP)
public interface GETransactionExporterConfig extends Config
{
	String GROUP = "ge-transaction-exporter";

	@ConfigItem(
		keyName = "exportEnabled",
		name = "Enable API export",
