		tracker.observe(o(0, GrandExchangeOfferState.BUYING, 0), T);
		assertNull(tracker.observe(o(0, GrandExchangeOfferState.CANCELLED_BUY, 0), T + 1));
		assertTrue(tracker.state().pending.isEmpty());
